        {
          "step_id": "S01",
          "operation": "group_aggregate",
          "params": {
            "metrics": [
              {
                "function": "count",
                "field": null,
                "alias": "status_task_count"
              }
            ],
            "dimensions": [
              "field_0003"
            ]
          }
        },
        {
          "step_id": "S02",
          "operation": "sort",
          "params": {
            "field": "status_task_count",
            "direction": "desc"
          }
        }
      ]
    },
    {
      "task_id": "T03",
      "title": "各项目工时投入统计",
      "business_question": "各项目的总工时和平均工时是多少？以识别资源投入的差异。",
      "priority": "P1",
      "priority_reason": "提供量化指标以支持'差异'分析，比单纯计数更能反映业务负载情况，属于重要补充分析。",
      "requirement_ids": [
        "C01"
      ],
      "depends_on": [],
      "missing_inputs": [],
      "steps": [
        {
          "step_id": "S01",
          "operation": "group_aggregate",
          "params": {
            "metrics": [
              {
                "function": "sum",
                "field": "field_0004",
                "alias": "total_hours"
              },
              {
                "function": "avg",
                "field": "field_0004",
                "alias": "avg_hours"
              }
            ],
            "dimensions": [
              "field_0002"
            ]
          }
        },
        {
          "step_id": "S02",
          "operation": "sort",
          "params": {
            "field": "total_hours",
            "direction": "desc"
          }
        }
      ]
    }
  ]
